def content(t,admin=False):
    title=t('사이트·관리자 패치노트','Website & administration changelog') if admin else t('Threadle 패치노트','Threadle changelog')
    intro=t('사이트와 운영 관리 화면의 변경 사항입니다.','Changes to the website and operational administration.') if admin else t('Discord에서 사용하는 Threadle의 새 기능과 개선 사항입니다.','New features and improvements to Threadle in Discord.')
    body='<section class="changelog-page"><h1>'+title+'</h1><p class="page-intro">'+intro+'</p>'
    if admin:body+='<p><a href="/connect/admin">'+t('관리자로 돌아가기','Back to administration')+'</a></p>'
    for version,ko,en,items in (ADMIN_RELEASES if admin else RELEASES):
        body+='<article class="patch-entry"><p class="patch-label">'+version+'</p><div class="card"><h2>'+t(ko,en)+'</h2><ul>'
        body+=''.join('<li>'+t(ko,en)+'</li>' for ko,en in items)
        body+='</ul></div></article>'
    return body+'</section>'
